def resolve(versions,reference):
    if reference!='latest' and (type(reference) is not int or reference<=0):raise ValueError('latest or positive version required')
    by_id={}
    for version in versions:
        ident=version.get('version');state=version.get('state')
        if type(ident) is not int or ident<=0 or ident in by_id or state not in ('ENABLED','DISABLED','DESTROYED'):raise ValueError('unique explicit versions and states required')
        if state=='ENABLED' and not isinstance(version.get('value'),str):raise ValueError('enabled fixture payload must be a string')
        by_id[ident]=version
    if not by_id:raise ValueError('no versions')
    ident=max(by_id) if reference=='latest' else reference
    version=by_id.get(ident)
    if version is None or version['state']!='ENABLED':raise ValueError('selected version unavailable; never fall back')
    return {'version':ident,'value':version['value']}
def start_environment(versions,reference):
    return resolve(versions,reference)
def read_latest_volume(versions):
    return resolve(versions,'latest')
